/**
 * Shared chart-level theme defaults composed into every chart-type module's
 * `themeTemplate`.
 *
 * Per `defaults.md`, module `themeTemplate`s are the canonical home for runtime
 * defaults. Each chart-type module (`CartesianChartModule`, `PolarChartModule`,
 * `StandaloneChartModule`, `TopologyChartModule`, …) merges this constant via
 * `mergeDefaults` so chart-level Normalised keys are guaranteed populated
 * post-theme-merge.
 *
 * Add an entry here only when the default genuinely applies to every chart
 * type. Per-chart-type overrides live in the relevant module's own
 * `themeTemplate`.
 */
export declare const commonChartThemeTemplate: {
    mode: string;
    suppressFieldDotNotation: boolean;
    keyboard: {
        enabled: boolean;
        initialFocus: string;
    };
    touch: {
        dragAction: string;
    };
    minHeight: number;
    minWidth: number;
    background: {
        visible: boolean;
        fill: {
            $ref: string;
        };
    };
    padding: {
        $applyPadding: {
            $ref: string;
        };
    };
    seriesArea: {
        border: {
            enabled: boolean;
            stroke: {
                $ref: string;
            };
            strokeOpacity: number;
            strokeWidth: number;
        };
        cornerRadius: number;
        padding: {
            $applyPadding: {
                $if: (number | {
                    $path: string;
                })[];
            };
        };
    };
    title: {
        cornerRadius: number;
        border: {
            enabled: boolean;
            strokeWidth: number;
            stroke: {
                $foregroundOpacity: number;
            };
        };
        padding: {
            $if: ({
                $path: string;
                left?: undefined;
                right?: undefined;
                top?: undefined;
                bottom?: undefined;
                $isUserOption?: undefined;
            } | {
                left: number;
                right: number;
                top: number;
                bottom: number;
                $path?: undefined;
                $isUserOption?: undefined;
            } | {
                $isUserOption: (string | number | {
                    left: number;
                    right: number;
                    top: number;
                    bottom: number;
                })[];
                $path?: undefined;
                left?: undefined;
                right?: undefined;
                top?: undefined;
                bottom?: undefined;
            })[];
        };
        enabled: boolean;
        text: string;
        spacing: {
            $if: (number | {
                $path: string;
            })[];
        };
        fontWeight: {
            $ref: string;
        };
        fontSize: {
            $ref: string;
        };
        lineHeight: import("./themeUtil").ThemeLineHeightOperation;
        fontFamily: {
            $ref: string;
        };
        color: {
            $ref: string;
        };
        wrapping: string;
        layoutStyle: {
            $ref: string;
        };
        textAlign: {
            $ref: string;
        };
    };
    subtitle: {
        cornerRadius: number;
        border: {
            enabled: boolean;
            strokeWidth: number;
            stroke: {
                $foregroundOpacity: number;
            };
        };
        padding: {
            $if: ({
                $path: string;
                left?: undefined;
                right?: undefined;
                top?: undefined;
                bottom?: undefined;
                $isUserOption?: undefined;
            } | {
                left: number;
                right: number;
                top: number;
                bottom: number;
                $path?: undefined;
                $isUserOption?: undefined;
            } | {
                $isUserOption: (string | number | {
                    left: number;
                    right: number;
                    top: number;
                    bottom: number;
                })[];
                $path?: undefined;
                left?: undefined;
                right?: undefined;
                top?: undefined;
                bottom?: undefined;
            })[];
        };
        enabled: boolean;
        text: string;
        spacing: number;
        fontWeight: {
            $ref: string;
        };
        fontSize: {
            $ref: string;
        };
        lineHeight: import("./themeUtil").ThemeLineHeightOperation;
        fontFamily: {
            $ref: string;
        };
        color: {
            $ref: string;
        };
        wrapping: string;
        layoutStyle: {
            $ref: string;
        };
        textAlign: {
            $ref: string;
        };
    };
    footnote: {
        cornerRadius: number;
        border: {
            enabled: boolean;
            strokeWidth: number;
            stroke: {
                $foregroundOpacity: number;
            };
        };
        padding: {
            $if: ({
                $path: string;
                left?: undefined;
                right?: undefined;
                top?: undefined;
                bottom?: undefined;
                $isUserOption?: undefined;
            } | {
                left: number;
                right: number;
                top: number;
                bottom: number;
                $path?: undefined;
                $isUserOption?: undefined;
            } | {
                $isUserOption: (string | number | {
                    left: number;
                    right: number;
                    top: number;
                    bottom: number;
                })[];
                $path?: undefined;
                left?: undefined;
                right?: undefined;
                top?: undefined;
                bottom?: undefined;
            })[];
        };
        enabled: boolean;
        text: string;
        spacing: number;
        fontSize: {
            $ref: string;
        };
        lineHeight: import("./themeUtil").ThemeLineHeightOperation;
        fontFamily: {
            $ref: string;
        };
        fontWeight: {
            $ref: string;
        };
        color: {
            $ref: string;
        };
        wrapping: string;
        layoutStyle: {
            $ref: string;
        };
        textAlign: {
            $ref: string;
        };
    };
    highlight: {
        enabled: boolean;
        drawingMode: {
            $if: (string | {
                $or: {
                    $some: ({
                        $and: ({
                            $or: {
                                $isSeriesType: string;
                            }[];
                            $isUserOption?: undefined;
                        } | {
                            $isUserOption: (string | boolean | {
                                $lessThan: (number | {
                                    $path: string;
                                })[];
                            })[];
                            $or?: undefined;
                        })[];
                        $path?: undefined;
                    } | {
                        $path: string;
                        $and?: undefined;
                    })[];
                }[];
            })[];
        };
    };
    tooltip: {
        enabled: boolean;
        delay: number;
        pagination: boolean;
        mode: {
            $if: (string | {
                $or: {
                    $and: ({
                        $isChartType: string;
                        $not?: undefined;
                        $greaterThan?: undefined;
                        $lessThan?: undefined;
                    } | {
                        $not: {
                            $hasSeriesType: string;
                        };
                        $isChartType?: undefined;
                        $greaterThan?: undefined;
                        $lessThan?: undefined;
                    } | {
                        $greaterThan: (number | {
                            $size: {
                                $path: string;
                            };
                        })[];
                        $isChartType?: undefined;
                        $not?: undefined;
                        $lessThan?: undefined;
                    } | {
                        $lessThan: (number | {
                            $size: {
                                $path: string;
                            };
                        })[];
                        $isChartType?: undefined;
                        $not?: undefined;
                        $greaterThan?: undefined;
                    })[];
                }[];
            })[];
        };
    };
    listeners: {};
};
